@Mod.EventBusSubscriber(modid="thaumcraft")
public final class BoreProbe {
 static final BlockPos P=new BlockPos(64008,190,8);static boolean cancel;
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 @SubscribeEvent public static void deny(BlockEvent.BreakEvent e){if(cancel&&e.getPos().closerThan(P,30))e.setResult(net.minecraftforge.common.util.Result.DENY);}
 static void ticks(ArcaneBore b,int n){for(int i=0;i<n;i++)b.tick();}
 static int count(Container c,Item item){int n=0;for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(item))n+=c.getItem(i).getCount();return n;}
 static ArcaneBore bore(ServerLevel l,Player p){var b=new ArcaneBore(BoreContent.TYPE.get(),l);b.setPos(P.getX()+.5,P.getY(),P.getZ()+.5);b.setNoGravity(true);b.configure(p.getUUID(),Direction.SOUTH);b.tool.setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));return b;}
 static void clean(ServerLevel l){for(var q:BlockPos.betweenClosed(P.offset(-6,-2,-5),P.offset(6,5,15)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(P.below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(P.below().west(),Blocks.REDSTONE_BLOCK.defaultBlockState());l.setBlockAndUpdate(P.west(),Blocks.CHEST.defaultBlockState());AuraData.get(l).put(AuraCell.key(P.getX()>>4,P.getZ()>>4),new AuraCell(200,200,0));}
 public static void run(ServerLevel l,ServerPlayer p){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)l.getChunk((P.getX()>>4)+x,z);clean(l);var recipe=l.recipeAccess().getRecipes().stream().filter(h->h.id().identifier().toString().equals("thaumcraft:infusion/arcane_bore")).findFirst().orElseThrow().value();check(recipe instanceof thaumcraft.infusion.InfusionRecipe,"Bore infusion failed to load");var infusion=(thaumcraft.infusion.InfusionRecipe)recipe;var components=new ArrayList<ItemStack>();for(String id:List.of("thaumcraft:plank_greatwood","thaumcraft:plank_greatwood","thaumcraft:mechanism_complex","thaumcraft:plate_brass","minecraft:diamond_pickaxe","minecraft:diamond_shovel","thaumcraft:morphic_resonator","thaumcraft:nugget_rareearth"))components.add(new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(id))));Collections.reverse(components);var input=new thaumcraft.infusion.InfusionInput(new ItemStack(thaumcraft.thaumaturgy.ThaumaturgyContent.TURRET.get().asItem()),components);check(infusion.matches(input,l)&&infusion.assemble(input).is(thaumcraft.content.SimpleContent.ITEMS.get("arcane_bore").get())&&infusion.research().equals("ARCANEBORE")&&infusion.instability()==4,"Native bore infusion incorrect");var b=bore(l,p);var at=P.south(3);l.setBlockAndUpdate(at,Blocks.DIAMOND_ORE.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(P.west());
  l.setBlockAndUpdate(P.below().west(),Blocks.AIR.defaultBlockState());ticks(b,600);check(l.getBlockState(at).is(Blocks.DIAMOND_ORE)&&b.charge()==0,"Unpowered bore excavates or drains aura");l.setBlockAndUpdate(P.below().west(),Blocks.REDSTONE_BLOCK.defaultBlockState());cancel=true;ticks(b,700);cancel=false;check(l.getBlockState(at).is(Blocks.DIAMOND_ORE)&&count(chest,Items.DIAMOND)==0&&b.charge()==10,"Cancelled break removed block, charged vis or generated loot");ticks(b,700);check(l.getBlockState(at).isAir()&&count(chest,Items.DIAMOND)==1,"Native drilling failed or duplicated ore loot");check(b.charge()==10||b.charge()==9.75F,"Unexpected vis payment");check(l.getBlockEntity(P.west())==chest,"Bore destroyed its side output chest");check(b.tool.getItem(0).getDamageValue()==0,"Pico wore before 50 successful blocks");thaumcraft.Thaumcraft.LOGGER.info("BORE64_POWER_PROTECTION_LOOT_OK");
  var ench=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT);var silk=new ItemStack(Items.DIAMOND_PICKAXE);silk.enchant(ench.getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);b.tool.setItem(0,silk);l.setBlockAndUpdate(at,Blocks.DIAMOND_ORE.defaultBlockState());ticks(b,700);check(count(chest,Items.DIAMOND_ORE)==1&&count(chest,Items.DIAMOND)==1,"Silk touch ignored");
  var s=new ItemStack(Items.DIAMOND_PICKAXE);s.setDamageValue(s.getMaxDamage()-1);b.tool.setItem(0,s);l.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());ticks(b,500);check(l.getBlockState(at).is(Blocks.STONE),"Almost broken pickaxe was used");b.tool.setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));for(int i=0;i<48;i++){l.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());ticks(b,600);check(l.getBlockState(at).isAir(),"Stone not mined "+i);}check(b.tool.getItem(0).getDamageValue()==1,"50 successful blocks did not cost exactly one durability");thaumcraft.Thaumcraft.LOGGER.info("BORE64_SILK_WEAR_OK");
  var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,l.registryAccess());b.saveWithoutId(out);var copy=new ArcaneBore(BoreContent.TYPE.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),out.buildResult()));check(copy.owned(p)&&copy.facing()==b.facing()&&copy.charge()==b.charge()&&ItemStack.matches(copy.tool.getItem(0),b.tool.getItem(0)),"Save/load lost owner, direction, charge or real tool");
  var menu=new BoreMenu(7,p.getInventory(),b.tool,b);p.getInventory().clearContent();check(!menu.slots.get(0).mayPlace(new ItemStack(Items.DIAMOND_SHOVEL)),"Invalid tool accepted");menu.quickMoveStack(p,0);check(b.tool.isEmpty()&&count(p.getInventory(),Items.DIAMOND_PICKAXE)==1,"Shift-click lost or duplicated real tool");thaumcraft.Thaumcraft.LOGGER.info("BORE64_SAVE_MENU_OK");
  b.tool.setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));l.setBlockAndUpdate(at,Blocks.CHEST.defaultBlockState());((ChestBlockEntity)l.getBlockEntity(at)).setItem(0,new ItemStack(Items.EMERALD,7));var oldItem=new net.minecraft.world.entity.item.ItemEntity(l,at.getX()+.5,at.getY()+1,at.getZ()+.5,new ItemStack(Items.GOLD_INGOT,5));oldItem.setNoGravity(true);l.addFreshEntity(oldItem);ticks(b,700);check(count(chest,Items.EMERALD)==7&&oldItem.isAlive()&&oldItem.getItem().getCount()==5,"Container contents lost/duplicated or pre-existing player item absorbed");
  clean(l);b=bore(l,p);AuraData.get(l).put(AuraCell.key(P.getX()>>4,P.getZ()>>4),new AuraCell(200,0,0));l.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());ticks(b,700);check(l.getBlockState(at).is(Blocks.STONE)&&b.charge()==0,"Zero-vis bore mined for free");l.setBlockAndUpdate(P,thaumcraft.content.SimpleContent.BLOCKS.get("activator_rail").get().defaultBlockState());check(l.getBlockState(P).hasProperty(PoweredRailBlock.POWERED),"Arcane rail missing power property");b.tool.setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));AuraData.get(l).put(AuraCell.key(P.getX()>>4,P.getZ()>>4),new AuraCell(200,200,0));l.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(l.getBlockState(P).getValue(PoweredRailBlock.POWERED),"Physical redstone did not power the arcane rail");ticks(b,600);check(l.getBlockState(at).is(Blocks.STONE),"Powered arcane rail failed to stop bore");l.setBlockAndUpdate(P.east(),Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(P.below().west(),Blocks.AIR.defaultBlockState());check(!l.getBlockState(P).getValue(PoweredRailBlock.POWERED),"Arcane rail did not lose physical power");ticks(b,600);check(l.getBlockState(at).isAir(),"Inactive arcane rail failed to start bore");thaumcraft.Thaumcraft.LOGGER.info("BORE64_INFUSION_CONTAINER_VIS_RAIL_OK");
 }
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!System.getProperty("thaumcraft.bookProbe","").equals("bore"))return;var l=e.getServer().overworld();e.getServer().tickRateManager().setFrozen(true);var p=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.randomUUID(),"BoreProof"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};p.setPos(Vec3.atCenterOf(P.west(4)));p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);new net.minecraft.server.network.ServerGamePacketListenerImpl(e.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};l.players().add(p);try{run(l,p);}finally{l.players().remove(p);}thaumcraft.Thaumcraft.LOGGER.info("BORE64_NATIVE_OK");e.getServer().halt(false);}
}
